import type { AnchorData } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { Decoration_Type, type Resolver } from './../../ricos-types/index.js';

export const getAnchorData: Resolver<AnchorData | undefined> = (content, _services, _editor) => {
  if (Array.isArray(content)) {
    const node = content.find(node => {
      return node.type.name === 'text';
    });
    if (node?.marks.some(mark => mark.type.name === Decoration_Type.ANCHOR)) {
      return node.marks[0].attrs.anchor;
    }
  }
  return undefined;
};
