import type { PmMarkConverter } from './../pm-converters/types.js';
import type { Link, LinkDecoration } from './../ricos-schema/next-schema/index.js';
import { Decoration_Type } from './../ricos-schema/next-schema/index.js';
import { isMaliciousUrl } from './../_shared/link/is-malicious-url.js';
import { fromTiptapLinkConverter } from './../_shared/link/link-converters.js';

export const linkConverter: PmMarkConverter = {
  fromPm: {
    type: Decoration_Type.LINK,
    convert: mark => {
      const { attrs } = mark;
      return [
        {
          type: Decoration_Type.LINK,
          linkData: {
            ...attrs,
            ...(attrs?.link ? { link: fromTiptapLinkConverter(attrs.link as any) as Link } : {}),
          },
        },
      ];
    },
  },
  toPm: {
    type: Decoration_Type.LINK,
    convert: decoration => {
      const { linkData } = decoration as LinkDecoration;
      return isMaliciousUrl(linkData?.link?.url || '')
        ? undefined
        : {
            type: Decoration_Type.LINK,
            attrs: {
              ...linkData,
            },
          };
    },
  },
};
