import { TextButton } from '@wix/design-system';
import React, { useContext } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import type { IToolbarItem, TFunction } from './../../ricos-types/index.js';

import classes from './anchor-link-button-scss.js';

const GO_TO_LABEL = 'LinkTo_Toolbar_GoTo';

// The "Go to" affordance is drawn twice — once by the plugin toolbar, once by external
// toolbars — and has to read as a link in both. Sharing the WDS props is what replaced the
// inline `text-decoration: underline` the external rendering used to carry.
const goToLabelProps = { size: 'small', underline: 'onHover' } as const;

/** The link toolbar's own "Go to" button. */
export const AnchorLinkButton = ({ toolbarItem }: { toolbarItem: IToolbarItem }) => {
  const { t } = useContext(RicosContext);

  return (
    <TextButton
      {...goToLabelProps}
      className={classes.goToButton}
      dataHook={toolbarItem.presentation?.dataHook}
      tabIndex={toolbarItem.presentation.tabIndex}
      onClick={e => {
        e.preventDefault();
        toolbarItem.commands.click();
      }}
      onMouseDown={e => {
        // Prevents the editor from losing focus
        e.preventDefault();
      }}
    >
      {t(GO_TO_LABEL)}
    </TextButton>
  );
};

/**
 * What external toolbars draw in place of the button above. They own the click and the
 * surrounding `<button>`, so this is the label alone — a button inside a button is invalid.
 */
export const AnchorLinkLabel = ({ t }: { t: TFunction }) => (
  <TextButton {...goToLabelProps} as="span" tabIndex={-1}>
    {t(GO_TO_LABEL)}
  </TextButton>
);
