import React from 'react';

import type { ToolbarButton } from './../../../ricos-types/index.js';

import { PLUGIN_TOOLBAR_BUTTON_ID } from '../plugin-toolbar-buttons-ids.js';
import { ToolbarButtonSeparator } from './toolbar-button-separator.js';

export const createSeparator = (attributes?: ToolbarButton['attributes']): ToolbarButton => {
  return {
    id: PLUGIN_TOOLBAR_BUTTON_ID.SEPARATOR,
    type: 'separator',
    icon: ToolbarButtonSeparator,
    renderer: () => <ToolbarButtonSeparator />,
    attributes,
  };
};
